import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Recorrido, tono, Regla, Ondas, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const PIEDR1 = en('piedritas'), PIEDR2 = en('piedritas', 2), PIEDR3 = en('piedritas', 3), OIDOS = en('oídos');
const TIMP = en('tímpano'), ADENTRO = en('adentro'), BOLSITAS = en('bolsitas'), LIQUIDO = en('líquido');
const EN1 = en('En'), PISO = en('piso'), ALFOMBRA = en('alfombra'), PEL1 = en('pelitos'), PEL2 = en('pelitos', 2), PEL3 = en('pelitos', 3);
const CRIST1 = en('cristales'), CRIST2 = en('cristales', 2), CRIST3 = en('cristales', 3), DIMIN = en('diminutos'), PEQ = en('pequeños'), GRANO = en('grano'), ARENA = en('arena');
const ESTAN = en('Están'), HECHOS = en('hechos'), CARBON = en('carbonato'), CALCIO = en('calcio'), MISMO = en('mismo'), TIZA = en('tiza');
const CUANDO1 = en('Cuando'), CUANDO2 = en('Cuando', 2), INCLINAS = en('inclinas'), PESAN = en('pesan'), DOBLAN = en('doblan');
const CARRO = en('carro'), ARRANCA = en('arranca'), ATRAS = en('atrás'), CEREBRO = en('cerebro'), EMPUJON = en('empujón');
const POR = en('Por'), SABES = en('sabes'), SUELO = en('suelo'), CIERRES = en('cierres'), OJOS = en('ojos');
const PERO = en('Pero'), SUELTAN = en('sueltan'), RUEDAN = en('ruedan'), TUBITO = en('tubito'), ESTAR = en('estar');
const ENTONCES = en('Entonces'), GIRARTE = en('girarte'), CAMA = en('cama'), CUARTO = en('cuarto'), VUELTAS = en('vueltas');
const MEDICOS = en('médicos'), MOVIM = en('movimientos'), CABEZA2 = en('cabeza', 2), DEVUELVEN = en('devuelven'), LUGAR = en('lugar');
const CADA = en('Cada', 2), PARAS = en('paras'), DERECHO = en('derecho'), DICIENDO = en('diciendo');
const DALE = en('Dale'), MAREA = en('marea'), BUS = en('bus'), BARCO = en('barco'), HAMACA = en('hamaca');

const LIMA = '#E7FF00';
const abre = (s: number, a: number, b: number, c: number) => interpolate(s, [a, b, c], [0, 1, 0], {...clamp, easing: Easing.inOut(Easing.sin)});
const rot = (px: number, py: number, cx: number, cy: number, deg: number): [number, number] => {
  const a = (deg * Math.PI) / 180, dx = px - cx, dy = py - cy;
  return [cx + dx * Math.cos(a) - dy * Math.sin(a), cy + dx * Math.sin(a) + dy * Math.cos(a)];
};

const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 3000}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

type Parada = {t: number; x: number; y: number; zoom: number};
const Lugar: React.FC<{tipo: 'piel' | 'celulas' | 'fibra' | 'papel'; base: string; linea: string; luz: string; semilla: number; bx: number; by: number; bc: string; paradas: Parada[]; w?: number; children: React.ReactNode}> = ({tipo, base, linea, luz, semilla, bx, by, bc, paradas, w, children}) => (
  <AbsoluteFill style={{background: '#10101A'}}>
    <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
    <Camara paradas={paradas}>
      <Brillo x={bx} y={by} r={720} color={bc} />
      <Mundo w={w}>{children}</Mundo>
    </Camara>
  </AbsoluteFill>
);

// ---------- piezas dibujadas ----------
// el cristal blanco (otolito): protagonista
const Cristal: React.FC<{x: number; y: number; sc?: number; ang?: number; op?: number; cara?: boolean; brillo?: number}> = ({x, y, sc = 1, ang = 0, op = 1, cara = false, brillo = 0.5}) => {
  const {s} = useS();
  const g = 0.6 + 0.4 * Math.sin(s * 5 + x * 0.03);
  return (
    <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc})`} opacity={op}>
      <defs><linearGradient id="crG" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#FFFFFF" /><stop offset="100%" stopColor="#BFE0FA" /></linearGradient></defs>
      <circle r={96} fill="rgba(255,255,255,0.28)" opacity={brillo * g} />
      <polygon points="0,-62 48,-30 48,30 0,62 -48,30 -48,-30" fill="url(#crG)" stroke="#FFFFFF" strokeWidth={4} strokeLinejoin="round" />
      <path d="M -48 -30 L 0 0 L 48 -30 M 0 0 L 0 62" stroke="rgba(110,160,215,0.7)" strokeWidth={3} fill="none" />
      <polygon points="-32,-30 -8,-44 -8,-20 -32,-6" fill="rgba(255,255,255,0.9)" />
      {cara && [-1, 1].map((k) => <g key={k}><ellipse cx={k * 17} cy={14} rx={5.5} ry={7.5} fill="#1A3A5A" /><circle cx={k * 17 + 1.8} cy={11} r={2.2} fill="#fff" /></g>)}
      {cara && <path d="M -9 32 Q 0 40 9 32" stroke="#1A3A5A" strokeWidth={4} fill="none" strokeLinecap="round" />}
    </g>
  );
};

// alfombra de pelitos que ondean
const Pelos: React.FC<{x0: number; x1: number; y: number; n: number; doblar?: number; lima?: number; alto?: number}> = ({x0, x1, y, n, doblar = 0, lima = 0, alto = 70}) => {
  const {s} = useS();
  return <>{Array.from({length: n}).map((_, i) => {
    const x = x0 + ((x1 - x0) * i) / (n - 1);
    const b = doblar * alto * 0.5 + Math.sin(s * 2.2 + i * 0.8) * alto * 0.07;
    const col = lima > 0.5 ? LIMA : '#E27A9A';
    return <g key={i}><path d={`M ${x} ${y} Q ${x + b * 0.25} ${y - alto * 0.6} ${x + b} ${y - alto}`} stroke={col} strokeWidth={Math.max(3, alto * 0.08)} fill="none" strokeLinecap="round" /><circle cx={x + b} cy={y - alto} r={Math.max(3, alto * 0.08)} fill={col} /></g>;
  })}</>;
};

// lente de aumento: dentro de la bolsita, piso de pelitos con cristales encima
const Lente: React.FC<{id: string; x: number; y: number; r: number; ang?: number; slide?: number; doblar?: number; lima?: number; n?: number; op?: number; children?: React.ReactNode}> = ({id, x, y, r, ang = 0, slide = 0, doblar = 0, lima = 0, n = 7, op = 1, children}) => {
  const alto = r * 0.3, piso = r * 0.38;
  return (
    <g transform={`translate(${x} ${y})`} opacity={op}>
      <defs><clipPath id={id}><circle r={r} /></clipPath><radialGradient id={id + 'g'} cx="40%" cy="30%" r="80%"><stop offset="0%" stopColor="#D8F6F2" /><stop offset="100%" stopColor="#6FC8D8" /></radialGradient></defs>
      <circle r={r + 20} fill="rgba(111,168,220,0.4)" />
      <g clipPath={`url(#${id})`}>
        <circle r={r} fill={`url(#${id}g)`} opacity={0.92} />
        <g transform={`rotate(${ang})`}>
          <path d={`M ${-r * 1.6} ${piso} L ${r * 1.6} ${piso} L ${r * 1.6} ${r * 1.6} L ${-r * 1.6} ${r * 1.6} Z`} fill="#E9B7C4" />
          <Pelos x0={-r * 0.9} x1={r * 0.9} y={piso} n={15} doblar={doblar} lima={lima} alto={alto} />
          {Array.from({length: n}).map((_, i) => <Cristal key={i} x={-r * 0.62 + i * ((r * 1.24) / Math.max(1, n - 1)) + slide * r + doblar * alto * 0.5} y={piso - alto - r * 0.07} sc={r / 900} brillo={0.3} />)}
          {children}
        </g>
      </g>
      <circle r={r} fill="none" stroke="#6FA8DC" strokeWidth={10} />
    </g>
  );
};

// cabeza de perfil mirando a la derecha; la oreja queda en (-40, 20)
const Perfil: React.FC<{x: number; y: number; sc?: number; tilt?: number; ojo?: number}> = ({x, y, sc = 1, tilt = 0, ojo = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${tilt} 0 300) scale(${sc})`}>
    <rect x={-80} y={170} width={170} height={300} rx={40} fill="#D9A07A" />
    <path d="M -240 -60 C -240 -260 80 -300 220 -170 C 270 -120 270 -60 285 -10 L 335 42 L 285 72 C 280 150 250 240 120 270 C 0 300 -240 240 -240 80 Z" fill="#E9B58E" stroke="#8A5A3A" strokeWidth={6} />
    <path d="M -252 -40 C -276 -270 100 -336 232 -184 C 140 -204 40 -204 -60 -134 C -120 -84 -200 -92 -252 -40 Z" fill="#3A2418" />
    <ellipse cx={-40} cy={20} rx={46} ry={74} fill="#E2A47E" stroke="#8A5A3A" strokeWidth={6} />
    <path d="M -52 -30 C -10 -20 -10 50 -44 66" stroke="#B9805E" strokeWidth={7} fill="none" strokeLinecap="round" />
    {ojo > 0.5 ? <path d="M 138 -44 Q 158 -30 178 -44" stroke="#241410" strokeWidth={7} fill="none" strokeLinecap="round" /> : <><ellipse cx={158} cy={-44} rx={9} ry={12} fill="#241410" /><circle cx={161} cy={-48} r={3.5} fill="#fff" /></>}
    <path d="M 160 160 Q 200 176 238 156" stroke="#7A3A2A" strokeWidth={6} fill="none" strokeLinecap="round" />
  </g>
);

const Carita: React.FC<{x: number; y: number; sc?: number; mareo?: number; cerrado?: boolean}> = ({x, y, sc = 1, mareo = 0, cerrado = false}) => {
  const {s} = useS();
  const piel = mareo > 0.5 ? '#CBE0A4' : '#F1C9A5';
  const esp = (cx: number, dir: number) => {
    const p = Array.from({length: 22}).map((_, i) => { const a = i * 0.7 + s * 6 * dir, r = 2 + i * 0.95; return `${i ? 'L' : 'M'} ${cx + Math.cos(a) * r} ${-4 + Math.sin(a) * r}`; }).join(' ');
    return <path d={p} stroke="#241410" strokeWidth={3.5} fill="none" strokeLinecap="round" />;
  };
  return (
    <g transform={`translate(${x} ${y}) scale(${sc})`}>
      <circle r={86} fill={piel} stroke="rgba(90,50,30,0.5)" strokeWidth={4} />
      <path d="M -84 -14 C -92 -104 -30 -128 8 -122 C 66 -116 96 -74 84 -10 C 64 -58 22 -78 -18 -74 C -52 -70 -72 -50 -84 -14 Z" fill="#3A2418" />
      <ellipse cx={-54} cy={30} rx={18} ry={11} fill="rgba(235,110,110,0.32)" /><ellipse cx={54} cy={30} rx={18} ry={11} fill="rgba(235,110,110,0.32)" />
      {mareo > 0.5 ? <>{esp(-32, 1)}{esp(32, -1)}</> : cerrado ? [-1, 1].map((k) => <path key={k} d={`M ${k * 32 - 14} -2 Q ${k * 32} 12 ${k * 32 + 14} -2`} stroke="#241410" strokeWidth={6} fill="none" strokeLinecap="round" />) : [-1, 1].map((k) => <g key={k}><ellipse cx={k * 32} cy={-4} rx={9} ry={12} fill="#241410" /><circle cx={k * 32 + 3} cy={-8} r={3.5} fill="#fff" /></g>)}
      {mareo > 0.5 ? <path d={`M -26 48 Q -13 ${38 + 6 * Math.sin(s * 8)} 0 48 T 26 48`} stroke="#4A6A2A" strokeWidth={6} fill="none" strokeLinecap="round" /> : <path d="M -18 46 Q 0 60 18 46" stroke="#7A3A2A" strokeWidth={6} fill="none" strokeLinecap="round" />}
    </g>
  );
};

// ---------- E1 y E12: la oreja en primer plano con rayos X ----------
const Oreja: React.FC<{v: 1 | 2}> = ({v}) => {
  const {s, spr, lin} = useS();
  const T = v === 1 ? 0 : CADA;
  const tilt = v === 1 ? 0 : interpolate(s, [T, T + 0.4, PARAS - 0.1, PARAS + 0.5], [-24, -24, -24, 0], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const brilla = v === 1 ? 0.5 + 0.5 * spr(PIEDR1, 9, 120) : 0.4 + 0.6 * spr(PIEDR3, 9, 120);
  const [ex, ey] = rot(760 - 40 * 1.9, 1000 + 20 * 1.9, 760, 1000 + 300, tilt);
  const paradas = v === 1
    ? [{t: 0, x: 640, y: 1000, zoom: 1.0}, {t: OIDOS - 0.6, x: ex, y: ey, zoom: 1.55}, {t: OIDOS + 0.9, x: ex, y: ey, zoom: 1.9}]
    : [{t: T - 0.2, x: 640, y: 980, zoom: 1.0}, {t: PARAS, x: ex, y: ey, zoom: 1.4}, {t: PIEDR3 + 0.8, x: ex, y: ey, zoom: 1.85}];
  return (
    <Lugar tipo="piel" base="radial-gradient(circle at 40% 30%, #F4D8E0 0%, #E9B7C4 55%, #B98A9E 100%)" linea="rgba(150,90,110,0.3)" luz="rgba(255,235,240,0.3)" semilla={v + 40} bx={560} by={900} bc="rgba(255,225,235,0.6)" paradas={paradas}>
      <Perfil x={760} y={1000} sc={1.9} tilt={tilt} ojo={v === 2 && tilt === 0 ? 0 : 0} />
      <g>
        <circle cx={ex} cy={ey} r={196} fill="rgba(150,220,230,0.35)" stroke="#6FA8DC" strokeWidth={10} />
        <Lente id={`lo${v}`} x={ex} y={ey} r={170} ang={-tilt} lima={v === 2 ? lin(PARAS + 0.4, PARAS + 0.8, 0, 1) : 0} n={7} op={0.88} />
      </g>
      <g transform={`translate(${ex} ${ey})`}><ellipse cx={0} cy={0} rx={87} ry={140} fill="none" stroke="#8A5A3A" strokeWidth={7} opacity={0.6} /></g>
      {Array.from({length: 9}).map((_, i) => <circle key={i} cx={ex + Math.cos(i * 0.7 + s * 2) * (210 + 14 * Math.sin(s * 3 + i))} cy={ey + Math.sin(i * 0.7 + s * 2) * (210 + 14 * Math.sin(s * 3 + i))} r={5 + (i % 3) * 2} fill="#fff" opacity={brilla * (0.5 + 0.4 * Math.sin(s * 6 + i))} />)}
      <Ondas x={ex} y={ey} t0={v === 1 ? PIEDR1 : PIEDR3} color="#FFFFFF" radio={340} />
    </Lugar>
  );
};

// ---------- E2: por dentro, canal, tímpano, caracol y bolsitas ----------
const Interior: React.FC = () => {
  const {s, lin} = useS();
  const pts: [number, number][] = [[-200, 1000], [450, 1000], [800, 1010], [1100, 1060], [1300, 1010]];
  const t0 = TIMP - 0.25, t1 = BOLSITAS + 0.2;
  const vib = golpe(s, TIMP + 0.1, 40, 5) * 8;
  const espiral = Array.from({length: 60}).map((_, i) => { const a = i * 0.22, r = 18 + i * 2.4; return `${i ? 'L' : 'M'} ${1010 + Math.cos(a) * r} ${1090 + Math.sin(a) * r}`; }).join(' ');
  const onda = (k: number) => Math.sin(s * 2 + k) * 14;
  return (
    <Lugar tipo="celulas" base="radial-gradient(circle at 50% 40%, #F4C9D6 0%, #E9B7C4 50%, #B27A92 100%)" linea="rgba(150,70,110,0.28)" luz="rgba(255,225,235,0.25)" semilla={41} bx={800} by={1000} bc="rgba(255,215,230,0.6)" w={3200}
      paradas={[{t: TIMP - 0.6, x: -100, y: 1000, zoom: 1.3}, ...seguir(pts, t0, t1, 1.25, 6), {t: LIQUIDO + 0.2, x: 1350, y: 1020, zoom: 1.45}]}>
      <path d="M -600 1000 L 560 1000" stroke="#C97A92" strokeWidth={250} strokeLinecap="butt" />
      <path d="M -600 1000 L 560 1000" stroke="#F3C6D2" strokeWidth={186} strokeLinecap="butt" />
      {Array.from({length: 9}).map((_, i) => <line key={i} x1={-300 + i * 110} y1={930} x2={-300 + i * 110} y2={1070} stroke="rgba(200,120,150,0.35)" strokeWidth={6} />)}
      <ellipse cx={560 + vib} cy={1000} rx={28} ry={160} fill="#F8E6D8" stroke="#B9805E" strokeWidth={6} />
      {[0, 1, 2].map((i) => <rect key={i} x={650 + i * 54} y={965 + i * 8} width={40} height={18} rx={9} fill="#EADFC3" stroke="#B9A77E" strokeWidth={3} transform={`rotate(${i * 12} ${670 + i * 54} 975)`} />)}
      <path d={espiral} stroke="#E9A0B8" strokeWidth={34} fill="none" strokeLinecap="round" />
      <path d={espiral} stroke="#F7D0DC" strokeWidth={14} fill="none" strokeLinecap="round" />
      {[{y: 860, k: 0}, {y: 1190, k: 2}].map((b, i) => (
        <g key={i}>
          <path d={`M 1230 ${b.y} C 1230 ${b.y - 130} 1470 ${b.y - 130} 1470 ${b.y} C 1470 ${b.y + 110} 1230 ${b.y + 110} 1230 ${b.y} Z`} fill="rgba(111,200,216,0.55)" stroke="#6FA8DC" strokeWidth={8} />
          <path d={`M 1250 ${b.y + 30} Q 1300 ${b.y + 8 + onda(b.k)} 1350 ${b.y + 30} T 1450 ${b.y + 30}`} stroke="rgba(255,255,255,0.7)" strokeWidth={8} fill="none" />
          <path d={`M 1262 ${b.y + 84} L 1438 ${b.y + 84}`} stroke="#E27A9A" strokeWidth={8} strokeDasharray="4 12" strokeLinecap="round" />
          {[0, 1, 2].map((j) => <Cristal key={j} x={1290 + j * 60} y={b.y + 56} sc={0.2} brillo={0.4} />)}
        </g>
      ))}
      <path d="M 1500 820 C 1620 700 1760 780 1700 900" stroke="rgba(111,168,220,0.6)" strokeWidth={36} fill="none" strokeLinecap="round" />
      <Recorrido puntos={pts} t0={t0} t1={t1} color="rgba(255,255,255,0.5)" render={(x, y) => <Cristal x={x} y={y} sc={0.55} cara />} />
      {s >= t1 && <Cristal x={1300 + 6 * Math.sin(s * 3)} y={1010 + 6 * Math.cos(s * 2)} sc={0.55} cara />}
      <Ondas x={560} y={1000} t0={TIMP} color="#FFFFFF" radio={300} />
    </Lugar>
  );
};

// ---------- E3-E4: corte de la bolsita; la alfombra de pelitos y los cristales que caen ----------
const Bolsita: React.FC = () => {
  const {s, lin, spr} = useS();
  const caen = Array.from({length: 14}).map((_, i) => {
    const t0 = PEL2 - 0.7 + i * 0.14, tx = 160 + i * 58;
    const p = lin(t0, t0 + 0.7, 0, 1, Easing.in(Easing.quad));
    const prota = i === 7;
    return {x: prota ? 560 : tx, y: -200 + (1214 + 200) * (prota ? lin(CRIST1 - 0.5, CRIST1 + 0.2, 0, 1, Easing.in(Easing.quad)) : p), prota, show: s > (prota ? CRIST1 - 0.55 : t0 - 0.05)};
  });
  const grano = spr(GRANO - 0.15, 9, 110);
  return (
    <>
      <Lugar tipo="celulas" base="radial-gradient(circle at 50% 28%, #CFF3F0 0%, #6FC8D8 55%, #2A6A9A 100%)" linea="rgba(40,120,170,0.3)" luz="rgba(220,250,255,0.3)" semilla={42} bx={540} by={800} bc="rgba(210,250,255,0.6)"
        paradas={[{t: EN1 - 0.3, x: 540, y: 900, zoom: 1.0}, {t: ALFOMBRA - 0.3, x: 540, y: 1240, zoom: 1.5}, {t: CRIST1 - 0.4, x: 540, y: 1220, zoom: 1.5}, {t: CRIST1 + 0.7, x: 560, y: 1240, zoom: 2.4}, {t: PEQ - 0.5, x: 560, y: 1200, zoom: 1.6}, {t: PEQ, x: 540, y: 1000, zoom: 1.0}, {t: ESTAN - 0.3, x: 540, y: 1000, zoom: 1.0}]}>
        {Array.from({length: 12}).map((_, i) => <circle key={i} cx={60 + h(i) * 960} cy={300 + ((s * (30 + h(i + 3) * 30) + h(i + 7) * 900) % 900)} r={6 + h(i + 5) * 14} fill="rgba(255,255,255,0.3)" />)}
        <rect x={-100} y={1350} width={1280} height={600} fill="#E9B7C4" stroke="#B9809A" strokeWidth={6} />
        <Pelos x0={90} x1={990} y={1350} n={30} alto={130} lima={0} />
        {caen.map((c, i) => c.show ? <Cristal key={i} x={c.x} y={Math.min(1210, c.y)} sc={c.prota ? 0.55 : 0.26} ang={(i * 37) % 30 - 15} cara={c.prota} brillo={c.prota ? 0.8 : 0.3} /> : null)}
        <g transform={`translate(540 880) scale(${grano})`} opacity={grano > 0.02 ? 1 : 0}>
          <ellipse cx={0} cy={140} rx={250} ry={22} fill="rgba(0,0,0,0.2)" />
          <ellipse cx={0} cy={0} rx={270} ry={170} fill="#E3C48A" stroke="#A8864A" strokeWidth={8} />
          <ellipse cx={-70} cy={-60} rx={120} ry={60} fill="rgba(255,240,200,0.55)" />
          {Array.from({length: 18}).map((_, i) => <circle key={i} cx={-200 + h(i) * 400} cy={-110 + h(i + 9) * 220} r={3 + h(i + 2) * 5} fill="rgba(140,100,50,0.6)" />)}
          <Cristal x={170} y={-170} sc={0.3} cara brillo={0.8} />
        </g>
        <Ondas x={560} y={1210} t0={CRIST1} color="#FFFFFF" radio={300} />
      </Lugar>
      <Regla x={270} y={640} largo={540} t0={GRANO - 0.1} texto="grano de arena" vertical={false} />
    </>
  );
};

// ---------- E5: el cristal se vuelve tiza y escribe en el pizarrón ----------
const Pizarron: React.FC = () => {
  const {s, lin, spr} = useS();
  const aTiza = lin(CARBON - 0.45, CARBON - 0.1, 0, 1, Easing.inOut(Easing.cubic)) * (1 - lin(TIZA + 0.1, TIZA + 0.45, 0, 1));
  const p1 = lin(CARBON, CALCIO - 0.25, 0, 1), p2 = lin(CALCIO, MISMO - 0.1, 0, 1);
  const cx = p2 > 0.001 && p2 < 1 ? 200 + 600 * p2 : p1 < 1 ? 200 + 700 * p1 : 800;
  const cy = p2 > 0.001 && p2 < 1 ? 1120 : 900;
  const vuelve = spr(TIZA + 0.15, 10, 140);
  return (
    <Lugar tipo="papel" base="radial-gradient(circle at 50% 40%, #2C5A4C 0%, #1F3D35 60%, #10241E 100%)" linea="rgba(230,255,240,0.14)" luz="rgba(210,255,230,0.1)" semilla={43} bx={540} by={900} bc="rgba(200,255,225,0.25)"
      paradas={[{t: ESTAN - 0.3, x: 540, y: 1000, zoom: 1.0}, {t: TIZA + 1.0, x: 540, y: 1000, zoom: 1.06}]}>
