        <rect x={-300} y={300} width={1700} height={1000} fill="#9AD8E8" />
        <rect x={-300} y={1300} width={1700} height={700} fill="#F2D7A0" />
        <rect x={20} y={800} width={60} height={800} rx={20} fill="#7A5A3A" /><rect x={1000} y={800} width={60} height={800} rx={20} fill="#7A5A3A" />
        {[20, 1000].map((px, i) => [0, 1, 2, 3].map((j) => <path key={px + '_' + j} d={`M ${px + 30} 800 Q ${px + 30 + (i ? -1 : 1) * (70 + j * 20)} ${700 - j * 10} ${px + 30 + (i ? -1 : 1) * (190 + j * 30)} ${820 + j * 40}`} stroke="#3E8A4A" strokeWidth={26} fill="none" strokeLinecap="round" />))}
        <path d="M 80 930 Q 540 1260 1000 930" stroke="#E8A040" strokeWidth={90} fill="none" strokeLinecap="round" />
        <path d="M 80 930 Q 540 1260 1000 930" stroke="#C8782A" strokeWidth={10} fill="none" strokeDasharray="14 18" />
        <Carita x={400} y={1030} sc={1.15} mareo={1} />
        <rect x={470} y={1050} width={380} height={110} rx={55} fill="#6FA8DC" transform="rotate(8 650 1100)" />
      </g>)},
  ];
  const activo = s >= HAMACA - 0.3 ? 2 : s >= BARCO - 0.3 ? 1 : s >= BUS - 0.3 ? 0 : -1;
  return (
    <Lugar tipo="piel" base="radial-gradient(circle at 50% 35%, #F4DDE6 0%, #E9B7C4 55%, #B98A9E 100%)" linea="rgba(150,90,110,0.28)" luz="rgba(255,238,244,0.3)" semilla={50} bx={540} by={900} bc="rgba(255,230,240,0.6)"
      paradas={[{t: DALE - 0.2, x: 540, y: 1000, zoom: 1.0}, {t: BUS, x: 540, y: 1040, zoom: 1.08}, {t: BARCO, x: 540, y: 1040, zoom: 1.0}, {t: HAMACA + 1.2, x: 540, y: 1040, zoom: 1.12}]}>
      {activo < 0 && (
        <g>
          <rect x={-120} y={300} width={1320} height={1400} fill="#F4DDE6" />
          <Carita x={540} y={1030} sc={1.5} mareo={1} />
          <rect x={440} y={1170} width={200} height={300} rx={70} fill="#6FA8DC" />
          {Array.from({length: 6}).map((_, i) => <circle key={i} cx={540 + Math.cos(s * 3 + i * 1.05) * 200} cy={850 + Math.sin(s * 3 + i * 1.05) * 40} r={10} fill={LIMA} />)}
        </g>
      )}
      {paneles.map((p, i) => (i <= activo ? <g key={i}>{p.f()}</g> : null))}
    </Lugar>
  );
};

